for name,obj in [('research.json',{'schema_version':'assistant-workspace-research-r1','checked_at':'2026-10-28','scope_zh':'8项有限官方文档研究，未加入canonical；1历史停用实体+7当前或更名功能/产品。不是完整市场图谱。','items':items}),('sources.json',sources),('dedup.json',dedup),('unknowns.json',{'items':[{'id':x['id'],'unknowns':x['unknowns_zh']} for x in items],'blockers':[{'url':'https://www.perplexity.ai/hub/blog/introducing-perplexity-deep-research','error':'web.open: cannot be opened (non-retryable error)','handling':'未绕过；不从未读取正文推定首次发布日期；使用其他已读取官方帮助页支持功能。'}],'never_run':['登录或开通','调用产品模型','账号数据读取','用户文件上传','真实自动化','Mac操作','对外发布或发送']})]:
 (P/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
md=['# 通用助手与研究工作区：有限学习指南','', '核验日：2026-10-28。8个实体，全部 documentation-only / never-run。仅官方资料，不是使用实测或性能排名。canonical未修改。','', '## 先看重要区别','- ChatGPT agent当前帮助页说已不可用，旧启动段落仍在；仅作历史迁移练习。','- Cowork当前云端/统一体验不能套用2026年1月本地VM教程。','- Spaces→Projects、Labs→Create files and apps作为改名关系，而不是重复新品。','- Research功能、工作区容器、客户端表面和模型分别登记。','', '## 执行边界','下面的步骤都是可供将来授权后练习的设计稿。本轮只查官方网页并制作本地文件；不登录、不调用产品模型、不上传用户材料、不连接账号、不运行自动化。涉及分享/导出到外部服务也需单独授权。','']
S={s['id']:s for s in sources}
for x in items:
 md += ['## '+x['name'],f"- 类型：`{x['entity_type']}`；状态：`{x['lifecycle_status']}`",'- 范围：'+x['version_scope_zh'],'- 日期：'+json.dumps(x['dates'],ensure_ascii=False),'- 可用条件：'+x['availability_zh'],'- 价格：未核实，不猜测；套餐资格不等于账号已可用。','### 权限与人类确认']+['- '+v for v in x['permissions_and_human_confirmation_zh']]+['### 原创合成学习任务：'+x['learning_task']['title_zh']]+[f'{i+1}. {v}' for i,v in enumerate(x['learning_task']['steps_zh'])]+['### 输出验收']+['- '+v for v in x['learning_task']['acceptance_zh']]+['### 限制与未知']+['- '+v for v in x['limitations_zh']+x['unknowns_zh']]+['### 官方来源']+['- ['+S[s]['title']+']('+S[s]['url']+')' for s in x['source_ids']]+['','**执行状态：never-run。**','']
(P/'GUIDE.zh-CN.md').write_text('\n'.join(md))
(P/'EVIDENCE.md').write_text('# 来源证据账本\n\n以下为原创概括和定位，不是网页全文快照。访问日与发布/更新日严格分离。相对更新时间不换算成首发日期。搜索结果只用于发现；OpenAI采用已打开官方页面的具体范围，搜索摘录与打开版本差异保留为未知。\n\n'+'\n\n'.join(f"## {s['id']}\n[{s['title']}]({s['url']})\n\n定位：{s['evidence_locator']}\n\n{s['evidence_summary_zh']}\n\n事件：{s['event_date']}；文档更新：{s['document_updated']}；访问：{s['accessed_at']}" for s in sources))
(P/'README.md').write_text('# assistant-workspace-research-r1\n\n主交付：research.json（8实体）、GUIDE.zh-CN.md（中文合成学习指南）、sources.json/EVIDENCE.md（官方证据）、dedup.json（117案例/最终读取222节点核对；初始读取为211）、unknowns.json（未知与抓取失败）。\n\n所有产品操作 never-run；只做文档研究。ChatGPT agent仅历史登记；其余功能可用条件仍需实际账户核验。不改canonical、不作全覆盖声称。build.py仅生成本地研究文件，不调用模型或账号。\n')
